private bool HasReusableMainTasker()
{
    var tasker = MaaTasker;
    if (tasker == null)
        return false;

    try
    {
        var controller = tasker.Controller;
        if (controller == null)
            return false;

        if (tasker.IsRunning || tasker.IsStopping)
            return true;

        // A connected game controller does not imply a usable Python Agent.
        // Reuse the existing reset/reconnect path before submitting another job.
        // Running/stopping jobs returned above are never rebuilt mid-execution.
        var agentReady = !AgentHelper.HasAgentConfigs(Interface?.Agent)
            || (_agentStarted && _agentContexts.Count > 0
                && _agentContexts.All(context => context.Client is { IsAlive: true }));
        return controller.IsConnected && agentReady;
    }
    catch (ObjectDisposedException)
    {
        return false;
    }
    catch (Exception ex)
    {
        LoggerHelper.Warning($"检查主任务执行器状态失败：{ex.Message}");
        return false;
    }
}
